$(document).ready(function () {
    "use strict";
    var a = document.querySelector("#header"), e = new Headroom(a, {
        offset: 80,
        tolerance: 40,
        classes: {initial: "animated", pinned: "fadeInDown", unpinned: "fadeOutUp"}
    });
    e.init(), e.init();
    var n = $(".restaurant-listing");
    n.isotope({
        filter: "*",
        animationOptions: {duration: 750, easing: "linear", queue: !1}
    }), $("nav.primary ul a").click(function () {
        var a = $(this).attr("data-filter");
        return n.isotope({filter: a, animationOptions: {duration: 750, easing: "linear", queue: !1}}), !1
    });
    var i = $("nav.primary ul"), t = i.find("a");
});